cypress_script:
describe('Challenging DOM Action Buttons', () => {
  it('should click the baz button successfully', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a.button').contains('baz').should('be.visible').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
  });
  it('should not change the URL when clicking a non-existent button', () => {
    cy.visit('https://the-internet.herokuapp.com/challenging_dom');
    cy.get('a.button').contains('non-existent').should('not.exist');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/challenging_dom');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

 test.describe('Challenging DOM Action Buttons', () => {
   test('should click the baz button successfully', async ({ page }) => {
     await page.goto('https://the-internet.herokuapp.com/challenging_dom');
     const bazButton = page.locator('a.button').withText('baz');
     await expect(bazButton).toBeVisible();
     await bazButton.click();
     await expect(page).toHaveURL('https://the-internet.herokuapp.com/challenging_dom');
   });
   test('should not change the URL when clicking a non-existent button', async ({ page }) => {
     await page.goto('https://the-internet.herokuapp.com/challenging_dom');
     const nonExistentButton = page.locator('a.button').withText('non-existent');
     await expect(nonExistentButton).toBeHidden();
     await expect(page).toHaveURL('https://the-internet.herokuapp.com/challenging_dom');
   });
 });
